catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        g_form.hideFieldMsg('device_type');
        return;
    }

    // Call the client-callable Script Include via GlideAjax
    var ga = new GlideAjax('x_2240997_smarti_0.AssetInventoryUtils');
    ga.addParam('sysparm_name', 'checkStockAvailability');
    ga.addParam('sysparm_device_type', newValue);

    ga.getXMLAnswer(function(response) {
        var result = JSON.parse(response);
        g_form.hideFieldMsg('device_type');

        if (result && result.available) {
            g_form.showFieldMsg(
                'device_type',
                'Refurbished unit available in stock (' + result.assetTag + '). Ready for fast allocation upon approval.',
                'info'
            );
        } else {
            g_form.showFieldMsg(
                'device_type',
                'No refurbished inventory currently in stock. This request will route for new procurement.',
                'warning'
            );
        }
    });
}
